def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    threat_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > 0:
                    threat_bids.append(float(bid))

    if not alive_opps:
        return float(min(budget, 12.0))

    high_supply = supply >= 22
    low_supply = supply <= 17
    urgent = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    active_highest = max(threat_bids) if threat_bids else highest_prev

    rich_threats = 0
    for opp in alive_opps:
        if opp.get('budget', 0) >= budget * 0.9:
            rich_threats += 1

    if urgent:
        if active_highest >= 110:
            bid = 96.0
        elif active_highest >= 85:
            bid = active_highest + 2.5
        elif active_highest > 0:
            bid = max(63.0, active_highest + 3.0)
        else:
            bid = 68.0
    elif low_supply:
        if active_highest >= 110:
            bid = 34.0
        elif active_highest >= 85:
            bid = 56.0 if rich_threats >= 2 else 61.0
        elif active_highest >= 45:
            bid = active_highest + 1.75
        elif active_highest > 0:
            bid = max(38.0, active_highest + 2.0)
        else:
            bid = 36.0
    elif high_supply:
        if pressured and active_highest < 90:
            bid = max(28.0, active_highest + 1.0 if active_highest > 0 else 28.0)
        else:
            bid = 12.0 if hp > 5 else 20.0
    else:
        if active_highest >= 110:
            bid = 24.0 if hp > 5 else 52.0
        elif active_highest >= 85:
            bid = 44.0 if hp > 5 else 60.0
        elif active_highest >= 45:
            bid = active_highest + 1.5
        elif active_highest > 0:
            bid = max(30.0, active_highest + 2.0)
        else:
            bid = 26.0

    if day >= 8 and hp > 6 and no_water_days == 0:
        bid *= 0.85

    if budget < 40:
        bid = min(bid, max(8.0, budget * 0.7))
    elif budget < 100:
        bid = min(bid, budget * 0.85)
    else:
        bid = min(bid, budget)

    if urgent:
        bid = max(bid, min(budget, 62.0))

    if bid < 0:
        bid = 0.0

    return float(min(budget, round(bid, 2)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        try:
            if opp.get('alive', False):
                alive_opponents.append(opp)
        except Exception:
            continue

    if not alive_opponents:
        cap = DAILY_SALARY * 0.4
        return max(0.0, min(my_budget, cap))

    # Immediate reaction to yesterday's bids
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate aggressiveness: Cindy survived with very high average bid yesterday
    # Use highest_prev_bid as proxy; if it was high, expect continued competition.
    critical = (my_hp <= 2) or (my_no_water_days >= 2)

    # Supply pressure: higher supply usually lowers required bids, but in simultaneous bidding
    # we still need enough to secure water when hp is low.
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if supply_norm < 0.0:
        supply_norm = 0.0
    if supply_norm > 1.0:
        supply_norm = 1.0

    # Base target bid: undercut likely top bidder while staying competitive.
    # If Cindy-like aggression (highest_prev_bid large), bid slightly higher; otherwise bid moderate.
    if highest_prev_bid >= DAILY_SALARY * 0.9:
        target = DAILY_SALARY * (0.72 - 0.15 * supply_norm)
    else:
        target = DAILY_SALARY * (0.62 - 0.10 * supply_norm)

    # If we are critical, override to ensure survival.
    if critical:
        target = DAILY_SALARY * (0.88 - 0.05 * supply_norm)

    # If we are healthy and not under pressure, avoid overpaying.
    if my_hp >= 7 and my_no_water_days == 0:
        target = min(target, DAILY_SALARY * 0.58)

    # Cap by budget
    if my_budget <= 0.0:
        return 0.0
    bid = min(my_budget, target)

    # Never bid negative
    if bid < 0.0:
        bid = 0.0
    return float(bid)
